from typing import Optional
from google.adk.agents import LlmAgent

def issue_refund(order_id: str, amount: int) -> dict:
    """Refunds are processed using the order number and amount."""
    return {"status": "Refund completed", "amount": amount}

def check_refund_limit(tool, args, tool_context) -> Optional[dict]:
    if tool.name == "issue_refund" and args.get("amount", 0) > 100:
        return {"status": "Approval required", "reason": "Exceeded amount limit"}
    return None  #If it is within the limit, the tool will run as is.

def log_refund_result(tool, args, tool_context, tool_response) -> Optional[dict]:
    print(f"[{tool.name}] Input={args} Result={tool_response}")
    return None  #leave the result as is

support_agent = LlmAgent(
    name="support_agent",
    model="gemini-2.5-flash",
    instruction="Handle refund inquiries.",
    tools=[issue_refund],
    before_tool_callback=check_refund_limit,
    after_tool_callback=log_refund_result,
)
